function withNavigation(locale: Locale) {
  const dictionary = mergeDictionary(FALLBACK_DICTIONARY, localeOverrides[locale]);

  return {
    ...dictionary,
    navigation: {
      admin: Object.fromEntries(
        Object.entries(localizedNavigationLabels.admin).map(([key, value]) => [key, value[locale]]),
      ),
      mobile: Object.fromEntries(
        Object.entries(localizedNavigationLabels.mobile).map(([key, value]) => [key, value[locale]]),
      ),
      utility: { notifications: localizedNavigationLabels.utility.notifications[locale] },
    },
  };
}

export type Dictionary = ReturnType<typeof withNavigation>;

/**
 * 언어별 사전은 **처음 쓸 때 한 번만** 만든다(2026-10-22 첫 실행 속도 점검). 전엔 모듈을 불러오는 순간 3개 언어를 모두 깊게
 * 합쳐(`mergeDictionary`) 앱을 켤 때마다 중급 폰 기준 약 60ms 를 썼는데, 한 사람은 한 언어만 쓴다. 같은 언어는 늘 같은 객체를 돌려준다.
 */
const builtDictionaries: Partial<Record<Locale, Dictionary>> = {};

function buildDictionary(locale: Locale): Dictionary {
  return (builtDictionaries[locale] ??= withNavigation(locale));
}

export const dictionaries: Record<Locale, Dictionary> = {
  get ko() {
    return buildDictionary("ko");
  },
  get ja() {
    return buildDictionary("ja");
  },
  get en() {
    return buildDictionary("en");
  },
};

export function isLocale(value: string | null | undefined): value is Locale {
  return value === "ko" || value === "ja" || value === "en";
}

export function resolveLocale(value: Locale | string | null | undefined): Locale {
  if (isLocale(value)) return value;
  const normalized = (value ?? "").toLowerCase();
  if (normalized.startsWith("ja")) return "ja";
  if (normalized.startsWith("en")) return "en";
  return "ko";
}

/**
 * HTTP Accept-Language 헤더에서 지원되는 가장 알맞은 로케일을 추론한다.
 * 품질 값(q=)을 파싱해 선호도 순으로 정렬하고 ko/ja/en 으로 매핑한다.
 * 지원하지 않는 언어(zh, vi, …)만 있는 헤더는 "en" 으로 대체한다 — 그런 방문자는
 * 한국어보다 영어를 훨씬 더 자주 읽는다 (2026-10-23). 헤더가 아예 없으면 "ko" 유지.
 *
 * 예시:
 *   "ja-JP,ja;q=0.9,en-US;q=0.8"  → "ja"
 *   "ko-KR,ko;q=0.9"               → "ko"
 *   "en-US,en;q=0.9"               → "en"
 *   "zh-CN,zh;q=0.9"               → "en"  (unsupported → English)
 *   ""                             → "ko"  (no header)
 */
export function inferLocaleFromAcceptLanguage(header: string): Locale {
  if (!header) return "ko";
  const entries = header
    .split(",")
    .map((s) => {
      const [tag, qPart] = s.trim().split(";");
      const q = qPart ? parseFloat(qPart.replace("q=", "")) : 1.0;
      return { tag: (tag ?? "").trim().toLowerCase(), q: isNaN(q) ? 1.0 : q };
    })
    .sort((a, b) => b.q - a.q);
  for (const { tag } of entries) {
    if (tag.startsWith("ko")) return "ko";
    if (tag.startsWith("ja")) return "ja";
    if (tag.startsWith("en")) return "en";
  }
  return "en";
}

/**
 * 세션이 없을 때의 화면 언어(로그인 · 온보딩 · 공개 페이지 · 404 · `<html lang>`, 2026-10-23 한 곳으로).
 * `?lang=` → `stayops_locale` 쿠키 → Accept-Language. 각 단계는 **올바른 값일 때만** 쓰고, 틀린 값이면 다음 단계로
 * 넘어간다 — 예전 로그인 · 온보딩은 `?lang=xx` 처럼 틀린 쿼리가 오면 쿠키를 건너뛰고 바로 Accept-Language 로 갔다.
 */
export function resolvePreSessionLocale(input: {
  query?: string | null;
  cookie?: string | null;
  acceptLanguage?: string | null;
}): Locale {
  if (isLocale(input.query)) return input.query;
  if (isLocale(input.cookie)) return input.cookie;
  return inferLocaleFromAcceptLanguage(input.acceptLanguage ?? "");
}

export function getDictionary(locale: Locale | string | null | undefined): Dictionary {
  return buildDictionary(resolveLocale(locale));
}

export function getLocalizedText(
  text: LocalizedText | undefined | null,
  locale: Locale,
  fallback = "",
): string {
  if (!text) {
    return fallback;
  }
  return text[locale] ?? text.ko ?? text.en ?? fallback;
}
